        "testata": "France 24",
        "lingua_originale": "en",
        "titolo_orig": "Ahead of Trump-Xi summit, China warns on US arms sales to Taiwan",
        "testo_it": "Cina avverte USA su vendite armi a Taiwan prima del summit Trump-Xi.",
        "priorita": "Alta",
        "id_gruppo": 8,
